import pathlib, sys
fails = []
def apply(path, old, new):
    p = pathlib.Path(path)
    if not p.exists():
        fails.append(f'{path}: FILE NOT FOUND'); return
    s = p.read_text()
    if new in s:
        return  # already applied
    c = s.count(old)
    if c != 1:
        fails.append(f'{path}: anchor {"not found" if c==0 else "not unique"}'); return
    p.write_text(s.replace(old, new, 1))

def write_new(path, content):
    p = pathlib.Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content)

